[9136] = { en = "Savage Flora", tier = 4,
  t = "Woeste planten",
  d = "Ik maak een bijzonder soort wapenrusting, Dreamwalker genaamd, voor de dappere helden die Naxxramas binnengaan. Zij kunnen me de meeste materialen geven die ik nodig heb, maar ik zoek altijd mensen die savage fronds kunnen halen van de planten in onze wereld.$B$BMisschien vind je dit werk beneden je stand, maar zonder de fronds kan de wapenrusting niet gemaakt worden.$B$BIk ben ook in de bijzondere positie dat ik je kan betalen met een insigne naar keuze, omdat zowel de Dawn als de Crusade mij geld geven.$b",
  o = "Rayne in Light's Hope Chapel in de Eastern Plaguelands wil 30 Savage Fronds.",
  p = "Ik weet heel veel over de planten in onze wereld. Heb je aanwijzingen nodig?",
  c = "Ik ben je zeer dankbaar, $N.$B$B<Rayne buigt.>$B$BVergeet niet dat ik altijd fronds aanneem.",
  g = { {"woeste", "savage (woest)"}, {"wapenrusting", "armor"}, {"genaamd", "called, named"}, {"dappere", "brave (dapper)"}, {"beneden je stand", "beneath you"}, {"insigne", "insignia"}, {"naar keuze", "of your choice"}, {"zowel", "both (zowel ... als)"}, {"aanwijzingen", "directions (aanwijzing)"}, {"dankbaar", "grateful, obliged"}, {"buigt", "bows (buigen)"}, {"aanneem", "accept (aannemen)"} },
},

[9137] = { en = "Savage Fronds", tier = 4,
  t = "Woeste bladeren",
  p = "Voor elke bundel fronds die je mij brengt, betaal ik je met een insigne naar keuze: van de Dawn of van de Crusade.$B$BInsignes kun je bij de Quartermaster inleveren voor verschillende beloningen.",
  c = "Dank je, $N. Jouw werk is van groot belang voor het succes van onze strijd tegen de Scourge.",
  g = { {"bundel", "bundle"}, {"insigne", "insignia"}, {"naar keuze", "of your choice"}, {"inleveren", "to turn in"}, {"beloningen", "rewards (beloning)"}, {"van groot belang", "vital, very important"}, {"strijd", "campaign, fight"} },
},

[9141] = { en = "They Call Me \"The Rooster\"", tier = 4,
  t = "Ze noemen me \"De Haan\"",
  d = "Wil je een opdrachtbrief? Wat? Denk je dat ik je een zeer gewilde werkorder geef, alleen omdat je hier komt opdagen? Dacht het niet, groentje. Ambachtslieden uit de hele wereld bieden op werk hier aan het front.$B$BAls je een werkorder wilt, moet je me laten zien dat je bereid bent te bloeden voor de zaak. Breng me een valor token, dan praten we verder.$B$BEn er is maar één manier om die in je vieze kleine groentjeshandjes te krijgen: aan het doden!",
  o = "Dispatch Commander Metz in Light's Hope Chapel in de Eastern Plaguelands wil een Argent Dawn Valor Token.$b",
  p = "<Commander Metz kauwt op zijn sigaar.>$B$BWat is er? Ik ben een drukbezet man.",
  c = "Goed, zo werkt het: voor elk valor token dat je inlevert, geef ik je een nieuwe opdrachtbrief. Je voert de order op die brief uit en levert de order af bij Packmaster Stonebruiser. Begrepen? Mooi. En nu wegwezen.",
  g = { {"haan", "rooster"}, {"opdrachtbrief", "writ, work order letter"}, {"gewilde", "sought after (gewild)"}, {"opdagen", "to show up"}, {"groentje", "scrub, newbie"}, {"ambachtslieden", "crafters (ambachtsman)"}, {"bieden", "bid"}, {"bereid", "willing"}, {"de zaak", "the cause"}, {"vieze", "grubby (vies)"}, {"kauwt", "chews (kauwen)"}, {"drukbezet", "busy"}, {"inlevert", "turn in (inleveren)"}, {"wegwezen", "get lost, get out"} },
},

[9142] = { en = "Craftsman's Writ", tier = 4,
  t = "Ambachtsbrief",
  d = "Je kent het klappen van de zweep, jochie. Eén valor token levert je een craftsman's writ op.",
  p = "Je kent het klappen van de zweep, jochie. Eén valor token levert je een craftsman's writ op.",
  c = "Die heb je verdiend, groentje. En ga nu niet zeuren over je orders. Voer ze uit of vernietig ze.",
