[9165] = { en = "Writ of Safe Passage", tier = 4,
  t = "Brief van vrije doorgang",
  d = "Zonder de hulp van avonturiers had mijn karavaan het nooit gehaald! De Scourge kwam van alle kanten tevoorschijn om ons tegen te houden.$B$B<Guard Didier veegt het zweet van zijn voorhoofd.>$B$BNu moeten we hier wachten tot Field Marshal Chambers aankomt. Hij tekent je brief van vrije doorgang, die je terugbrengt naar Dispatch Commander Metz in Light's Hope Chapel.$B$BEn $N, let op wat je zegt in de buurt van Chambers. Hij is het type dat je hoofd eraf bijt en het door je luchtpijp terugspuugt - alleen doet hij het echt...",
  o = "Breng de getekende Writ of Safe Passage naar Dispatch Commander Metz in Light's Hope Chapel in de Eastern Plaguelands.",
  p = "Naam, rang en stamnummer!",
  c = "<Dispatch Commander Metz neemt de brief aan en tekent hem.>$B$BUitstekend werk, $N. Zelfs voortreffelijk! Neem dit aan als teken van onze waardering. Woordspeling niet bedoeld, groentje.",
  o2 = "Writ of Safe Passage getekend",
  g = { {"vrije doorgang", "safe passage"}, {"avonturiers", "adventurers (avonturier)"}, {"karavaan", "caravan"}, {"tevoorschijn", "out, into view"}, {"tegen te houden", "to stop (tegenhouden)"}, {"veegt", "wipes (vegen)"}, {"voorhoofd", "brow, forehead"}, {"luchtpijp", "windpipe"}, {"terugspuugt", "spits back (terugspugen)"}, {"rang", "rank"}, {"stamnummer", "serial number"}, {"voortreffelijk", "outstanding"}, {"waardering", "appreciation"}, {"woordspeling", "pun"} },
},

