[9197] = { en = "Craftsman's Writ - Gnomish Battle Chicken", tier = 4,
  t = "Ambachtsbrief - Gnomish Battle Chicken",
  d = "De drager van deze brief krijgt een insigne naar keuze als betaling, zodra de werkorder klaar is.$B$BWerkorder EN-0:$B$B4 Gnomish Battle Chickens.$B$BAlle voltooide orders moeten naar Packmaster Stonebruiser in Light's Hope Chapel in de Eastern Plaguelands gebracht worden.$B$BHet contract is ongeldig als ermee geknoeid is of als het beschadigd is.$B$B-Dispatch Commander Metz, The Argent Dawn",
