[9211] = { en = "The Ice Guard", tier = 4,
  t = "De Ice Guard",
  d = "Ah, de Ice Guard. Het is een dun laagje beschermende magie dat bepaalde stukken uitrusting bedekt. Wie vecht tegen wezens van vorst en ijs, is met de Ice Guard beter beschermd tegen hun aanvallen.$B$BZoals bij alles wat de Wrathcaster maakt, heeft het een prijs - een prijs die ik niet zal verlagen, hoe hard je ook jammert. Interesse?",
  o = "Mataus the Wrathcaster in Light's Hope Chapel in de Eastern Plaguelands wil 10 Insignia of the Crusade en 30 goud.",
  p = "Als deze wachters van de Argent Dawn er niet waren, zou je nu een vlek op deze vloer zijn.$b",
  c = "<Mataus steekt het goud in zijn zak.>$B$BVeel plezier met de reparatiekosten, $r. Naxxramas is 'onvriendelijk' voor wie er niet in ingewijd is.",
  g = { {"laagje", "thin layer, sheen (laag)"}, {"beschermende", "protective (beschermend)"}, {"bepaalde", "certain (bepaald)"}, {"uitrusting", "equipment"}, {"bedekt", "covers (bedekken)"}, {"wezens", "creatures (wezen)"}, {"vorst", "frost"}, {"verlagen", "to lower"}, {"jammert", "whimper (jammeren)"}, {"wachters", "guards (wachter)"}, {"vlek", "stain"}, {"reparatiekosten", "repair costs"}, {"ingewijd", "initiated (inwijden)"} },
},

[9213] = { en = "The Shadow Guard", tier = 4,
  t = "De Shadow Guard",
  d = "Een geniale schepping! Net als de Ice Guard gebruikt de Shadow Guard een dun laagje beschermende magie dat bepaalde stukken uitrusting bedekt. En net als de Ice Guard gaat de Shadow Guard je flink wat geld kosten.$B$B<Mataus houdt zijn hand op en wrijft zijn vingers over elkaar.>$B$BInteresse?",
  o = "Mataus the Wrathcaster in Light's Hope Chapel in de Eastern Plaguelands wil 10 Insignia of the Crusade en 30 goud.",
  p = "<Mataus gaapt.>$B$BGa weg, insect, tenzij je iets voor me hebt.",
  c = "<Mataus propt het goud in zijn gewaad.>$B$BWaarom sta je hier nog, $R? Onze zaken zijn afgehandeld.",
  g = { {"geniale", "of genius, brilliant (geniaal)"}, {"schepping", "creation"}, {"laagje", "thin layer, sheen (laag)"}, {"beschermende", "protective (beschermend)"}, {"uitrusting", "equipment"}, {"flink wat", "a good amount of"}, {"wrijft", "rubs (wrijven)"}, {"gaapt", "yawns (gapen)"}, {"tenzij", "unless"}, {"propt", "stuffs (proppen)"}, {"gewaad", "robe"}, {"afgehandeld", "done, settled (afhandelen)"} },
},

